using System;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UnityEngine.Rendering.Universal;
// Vendor SDK owns tracking, stereo rendering and passthrough. This bridge owns lesson interaction only.
public class LocomotiveSpatialBridge : MonoBehaviour {
 public LocomotiveController lesson; public Canvas desktopUI,spatialUI;public TMP_Text spatialStatus;
 public Camera view;public bool active,simulator; public float snapDistance=.06f,snapAngle=20f;
 public LocomotivePart held; Pose grip,relativeGrip; Vector3 socketPosition;Quaternion socketRotation;
 bool oldInput,oldEnvironment,oldFloor;Light[] lights;float[] biases;float oldShadowDistance;Camera previewCamera;Transform marker;Material markerMaterial;
 public void TogglePreview(){if(active){Detach();return;}if(!previewCamera){var go=new GameObject("空间预览相机");previewCamera=go.AddComponent<Camera>();previewCamera.CopyFrom(lesson.studioCamera);previewCamera.fieldOfView=55;previewCamera.nearClipPlane=.02f;previewCamera.farClipPlane=50;previewCamera.GetUniversalAdditionalCameraData().renderPostProcessing=true;}previewCamera.transform.SetPositionAndRotation(new Vector3(0,1.7f,2.35f),Quaternion.identity);previewCamera.transform.LookAt(new Vector3(0,1.06f,0));Attach(previewCamera,new Pose(new Vector3(0,.78f,0),Quaternion.identity),.16f,false);simulator=true;spatialStatus.text="空间交互预览 · 尚未接入头显 SDK";}
 public void Attach(Camera trackedView,Pose anchor,float scale,bool passthrough){
  if(!trackedView)throw new ArgumentNullException("trackedView");if(active)Detach();oldInput=lesson.inputEnabled;oldEnvironment=lesson.environment.activeSelf;lesson.ResetView();lesson.externalView=true;lesson.inputEnabled=false;lesson.studioCamera.enabled=false;view=trackedView;view.enabled=true;lesson.display.SetPositionAndRotation(anchor.position,anchor.rotation);lesson.display.localScale=Vector3.one*Mathf.Clamp(scale,.04f,1f);lesson.environment.SetActive(!passthrough);var floor=lesson.environment.transform.Find("Floor");if(floor){oldFloor=floor.gameObject.activeSelf;floor.gameObject.SetActive(false);}lights=FindObjectsOfType<Light>();biases=new float[lights.Length];for(int i=0;i<lights.Length;i++){biases[i]=lights[i].shadowNormalBias;lights[i].shadowNormalBias=biases[i]*scale;}var pipeline=QualitySettings.renderPipeline as UniversalRenderPipelineAsset;if(pipeline){oldShadowDistance=pipeline.shadowDistance;pipeline.shadowDistance=Mathf.Max(4,24*scale);}desktopUI.gameObject.SetActive(false);spatialUI.gameObject.SetActive(true);spatialUI.worldCamera=view;var panel=(RectTransform)spatialUI.transform;var flat=Vector3.ProjectOnPlane(view.transform.forward,Vector3.up).normalized;if(flat.sqrMagnitude<.1f)flat=Vector3.forward;panel.position=view.transform.position+flat*1.4f+Vector3.down*.85f;panel.rotation=Quaternion.LookRotation(panel.position-view.transform.position);active=true;simulator=false;lesson.ApplyPose();SetAdaptiveDetail(false);spatialStatus.text="空间教学 · 选择零件查看作用";
 }
 public void Detach(){if(!active)return;CancelGrab();active=false;simulator=false;if(previewCamera)previewCamera.enabled=false;desktopUI.gameObject.SetActive(true);spatialUI.gameObject.SetActive(false);lesson.display.SetPositionAndRotation(Vector3.zero,Quaternion.identity);lesson.display.localScale=Vector3.one;lesson.environment.SetActive(oldEnvironment);var floor=lesson.environment.transform.Find("Floor");if(floor)floor.gameObject.SetActive(oldFloor);if(lights!=null)for(int i=0;i<lights.Length;i++)if(lights[i])lights[i].shadowNormalBias=biases[i];var pipeline=QualitySettings.renderPipeline as UniversalRenderPipelineAsset;if(pipeline)pipeline.shadowDistance=oldShadowDistance;lesson.externalView=false;lesson.inputEnabled=oldInput;lesson.studioCamera.enabled=true;lesson.ResetView();lesson.SetCamera();view=null;}
 public LocomotivePart Hit(Ray ray){RaycastHit hit;if(Physics.Raycast(ray,out hit,20))return hit.collider.GetComponentInParent<LocomotivePart>();return null;}
 // SDK calls this once on trigger/pinch activation; gaze alone never activates a control.
 public bool ActivateRay(Ray ray){if(!active)return false;float best=float.PositiveInfinity;Button selected=null;foreach(var b in spatialUI.GetComponentsInChildren<Button>()){var rt=(RectTransform)b.transform;float distance;var plane=new Plane(rt.forward,rt.position);if(!plane.Raycast(ray,out distance)||distance<0||distance>=best)continue;var p=rt.InverseTransformPoint(ray.GetPoint(distance));if(rt.rect.Contains(new Vector2(p.x,p.y))){best=distance;selected=b;}}if(selected){selected.onClick.Invoke();return true;}var part=Hit(ray);if(!part)return false;lesson.Select(part);spatialStatus.text=part.partId+" · "+part.title+"\n"+part.explanation;return true;}
 public bool BeginGrab(LocomotivePart part,Pose worldGrip){if(!active||!part||held||!part.gameObject.activeInHierarchy||lesson.exploded)return false;if(lesson.assemblyLesson&&(lesson.assembled>=lesson.parts.Length||part!=lesson.parts[lesson.assembled]))return false;lesson.running=false;lesson.travel=false;lesson.ApplyPose();held=part;grip=worldGrip;var local=part.transform.localPosition;if(lesson.assemblyLesson)local-=part.explodeOffset;socketPosition=part.transform.parent.TransformPoint(local);socketRotation=part.transform.rotation;relativeGrip=new Pose(Quaternion.Inverse(grip.rotation)*(part.transform.position-grip.position),Quaternion.Inverse(grip.rotation)*part.transform.rotation);ShowSocket();return true;}
 public void MoveGrab(Pose worldGrip){if(held)grip=worldGrip;}
 public bool ReleaseGrab(){if(!held)return false;var p=held;Vector3 at=grip.position+grip.rotation*relativeGrip.position;Quaternion rotation=grip.rotation*relativeGrip.rotation;bool fits=Vector3.Distance(at,socketPosition)<=snapDistance&&Quaternion.Angle(rotation,socketRotation)<=snapAngle;held=null;if(marker)marker.gameObject.SetActive(false);if(fits&&lesson.assemblyLesson)lesson.NextPart();lesson.ApplyPose();spatialStatus.text=fits?"接口已对齐，零件就位":"未对准接口，已返回；请靠近绿色位置再放开。";return fits;}
 public void CancelGrab(){held=null;if(marker)marker.gameObject.SetActive(false);if(lesson)lesson.ApplyPose();}
 void ShowSocket(){if(!marker){var go=GameObject.CreatePrimitive(PrimitiveType.Sphere);go.name="装配接口提示";Destroy(go.GetComponent<Collider>());marker=go.transform;markerMaterial=new Material(Shader.Find("Universal Render Pipeline/Unlit"));markerMaterial.SetColor("_BaseColor",new Color(.1f,.8f,.35f));go.GetComponent<Renderer>().sharedMaterial=markerMaterial;}marker.position=socketPosition;marker.localScale=Vector3.one*.035f;marker.gameObject.SetActive(true);}
 void LateUpdate(){if(!active)return;if(held)held.transform.SetPositionAndRotation(grip.position+grip.rotation*relativeGrip.position,grip.rotation*relativeGrip.rotation);if(simulator&&Input.GetMouseButtonDown(0))ActivateRay(view.ScreenPointToRay(Input.mousePosition));}
 public void SetAdaptiveDetail(bool enabled){lesson.adaptiveDetail=enabled;foreach(var lod in lesson.locomotive.GetComponentsInChildren<LODGroup>(true))lod.ForceLOD(enabled?-1:0);}
 void OnDestroy(){if(marker)Destroy(marker.gameObject);if(markerMaterial)Destroy(markerMaterial);}
}
